    url,
    expectedTheme,
    flickerDetected: themeChanged || !earlyMatchesExpected,
    earlyScreenshot: earlyPath,
    finalScreenshot: finalPath,
    earlyBrightness: Math.round(earlyBrightness),
    finalBrightness: Math.round(finalBrightness),
    diagnosis
  };
}

